body.script:
(function () {
  var PATH = '/open-woowtech-agent';
  var INTENT = 'intent://open#Intent;scheme=io.woowtech.agent;package=io.woowtech.agent;S.browser_fallback_url=https%3A%2F%2Faiot.woowtech.io%2Fopen-woowtech-agent%3Fv%3Dfb;end';
  var v = 'x';
  var m = location.search.match(/v=([a-z0-9_]+)/);
  if (m) { v = m[1]; }
  var ua = navigator.userAgent;
  var where = ua.indexOf(' Line/') !== -1 ? 'line' : (ua.indexOf('Chrome/') !== -1 ? 'chrome' : 'other');
  var android = ua.indexOf('Android') !== -1;
  function ping(ev) { var i = new Image(); i.src = PATH + '?ping=' + ev + '-' + v + '-' + where + '-' + Date.now(); }
  function show(id) { document.getElementById(id).hidden = false; }
  ping('load');
  if (!android) { show('ios'); return; }
  if (v === 'fb') { document.querySelector('h1').textContent = '請手動開啟渥屋助理'; show('fallback'); return; }
  document.addEventListener('visibilitychange', function () { if (document.hidden) { ping('hidden'); } });
  document.getElementById('open').addEventListener('click', function () { ping('tap'); });
  if (v === 'b') { document.querySelector('h1').textContent = '請按下面的按鈕打開渥屋助理'; return; }
  setTimeout(function () { ping('auto'); location.href = INTENT; }, 500);
  setTimeout(function () { if (!document.hidden) { ping('stayed'); show('fail'); } }, 3500);
})();
